function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function snapshot(){return {settings:clone(active.settings),drafts:clone(active.drafts),look:active.look,target:active.target};}
function commit(){if(!active)return;const next=snapshot();if(equal(next,active.history[active.position]))return;active.history=active.history.slice(0,active.position+1);active.history.push(next);if(active.history.length>60)active.history.shift();active.position=active.history.length-1;updateStatus();saveSoon();}
