async function initStorage(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('motus-touch-local',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('Storage unavailable'));});const data=await new Promise((resolve,reject)=>{const req=db.transaction('workspace').objectStore('workspace').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(data){restoredView=data.view||null;folders=data.folders||[];filmHidden=!!data.filmHidden;const rows=data.photos||[],apart=rows.filter(p=>!p.demo&&!p.blob);/* workspaces saved before version 4 kept every photo file inside this one record; those are moved out on the next save */if(apart.length)await new Promise((resolve,reject)=>{const tx=db.transaction('workspace'),store=tx.objectStore('workspace');for(const p of apart){const req=store.get('photo:'+p.id);req.onsuccess=()=>{if(req.result){p.blob=req.result;savedFiles.add(p.id);}};}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});photos=rows.filter(p=>p.demo||p.blob).map(p=>({...p,url:p.demo?'assets/portrait.jpg':URL.createObjectURL(p.blob),thumbUrl:p.thumb?URL.createObjectURL(p.thumb):undefined,settings:{...defaults,...p.settings},drafts:p.drafts||{},target:p.target||'All people'}));}$('#storage-status').textContent='Saved on this device';}catch(error){storageFailed=true;$('#storage-status').textContent='Session only · storage unavailable';notify('Browser storage is unavailable. Export your photos before closing.');}}
function saveSoon(){clearTimeout(saveTimer);saveTimer=setTimeout(saveWorkspace,200);}
function saveWorkspace(){if(!db||storageFailed)return;try{const records=photos.map(({url,thumbUrl,blob,...p})=>p),ids=new Set(photos.map(p=>p.id));const tx=db.transaction('workspace','readwrite'),store=tx.objectStore('workspace');const added=photos.filter(p=>p.blob&&!savedFiles.has(p.id)),removed=[...savedFiles].filter(id=>!ids.has(id));for(const p of added)store.put(p.blob,'photo:'+p.id);for(const id of removed)store.delete('photo:'+id);store.put({photos:records,folders:clone(folders),filmHidden,version:4,view:{screen,activeId:active?.id,collection,moduleId,showHidden,viewerHeight,reshapeTab,studioTab,leftPanelOpen,rightPanelOpen,leftFloating,rightFloating,floatingPositions}},'current');tx.oncomplete=()=>{for(const p of added)savedFiles.add(p.id);for(const id of removed)savedFiles.delete(id);$('#storage-status').textContent='Saved on this device';};tx.onerror=()=>{storageFailed=true;$('#storage-status').textContent='Session only · storage full';notify('Local storage is full. Current edits still work; export before closing.');};}catch(error){storageFailed=true;$('#storage-status').textContent='Session only · not saved';}}
