async function makeThumb(photo,source){try{const image=source instanceof Blob?await createImageBitmap(source):source,w=image.naturalWidth||image.width,h=image.naturalHeight||image.height,k=Math.min(1,480/Math.max(w,h)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(w*k));c.height=Math.max(1,Math.round(h*k));const g=c.getContext('2d');g.imageSmoothingQuality='high';g.drawImage(image,0,0,c.width,c.height);image.close?.();const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.85));c.width=c.height=1;if(blob){photo.thumb=blob;photo.thumbUrl=URL.createObjectURL(blob);}}catch(error){}}
// photos imported before thumbnails existed get theirs in the background, one at a time
async function makeMissingThumbs(){const list=photos.filter(p=>!p.demo&&p.blob&&!p.thumb);if(!list.length)return;for(const p of list)if(photos.includes(p))await makeThumb(p,p.blob);saveSoon();if(screen==='library')renderLibrary();renderFilmstrip();if(screen==='welcome')renderRecent();}
function forgetPhoto(p){if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);if(p.thumbUrl)URL.revokeObjectURL(p.thumbUrl);}
