function collectionPhotos(){let rows=photos.filter(p=>collection==='archive'?p.archived:p.archived?false:collection==='hidden'?isHidden(p):collection==='all'?true:p.folderId===collection);if(collection!=='hidden'&&collection!=='archive'&&!showHidden)rows=rows.filter(p=>!isHidden(p));const term=$('#photo-search').value.trim().toLowerCase();if(term)rows=rows.filter(p=>p.name.toLowerCase().includes(term));return rows.sort($('#photo-sort').value==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>b.added-a.added);}
