function openFolderDialog(){$('#folder-name').value='';const ids=selected.size?[...selected]:screen==='editor'&&active?[active.id]:[];$('#folder-include').disabled=!ids.length;$('#folder-include').checked=!!ids.length;$('#folder-dialog').showModal();$('#folder-name').focus();}
$('#folder-form').onsubmit=e=>{e.preventDefault();const name=$('#folder-name').value.trim();if(!name)return;const f={id:uid(),name,hidden:false};folders.push(f);if($('#folder-include').checked){const ids=selected.size?selected:new Set(active&&screen==='editor'?[active.id]:[]);for(const p of photos)if(ids.has(p.id))p.folderId=f.id;}$('#folder-dialog').close();selected.clear();collection=f.id;setScreen('library');renderLibrary();saveSoon();notify(`Folder “${name}” created.`);};
