function applyViewTransform(){const frame=$('#image-frame'),stage=$('#stage');const limitX=Math.max(0,(frame.offsetWidth*zoom/100-stage.clientWidth)/2+24),limitY=Math.max(0,(frame.offsetHeight*zoom/100-stage.clientHeight)/2+35);panX=Math.max(-limitX,Math.min(limitX,panX));panY=Math.max(-limitY,Math.min(limitY,panY));frame.style.transform=`translate(${panX}px,${panY}px) scale(${zoom/100})`;$('#viewer-resize').setAttribute('aria-valuenow',String(stage.clientHeight));stage.classList.toggle('zoomed',zoom>100);}
